import sys


class Node:
    def __init__(self, value):
        self.value = value
        self.prev = None
        self.next = None


def build_dll_chain(values):
    head = None
    tail = None
    for v in values:
        node = Node(v)
        node.prev = tail
        if head is None:
            head = node
        else:
            tail.next = node
        tail = node
    return head


def build_singly(values):
    head = None
    tail = None
    for v in values:
        node = Node(v)
        if head is None:
            head = node
        else:
            tail.next = node
        tail = node
    return head


def tail_node(head):
    node = head
    while node.next is not None:
        node = node.next
    return node


def dll_forward(head):
    out = []
    node = head
    while node is not None:
        out.append(node.value)
        node = node.next
    return out


def dll_backward(head):
    node = tail_node(head)
    out = []
    while node is not None:
        out.append(node.value)
        node = node.prev
    return out


def build_circle(values):
    head = build_singly(values)
    tail = tail_node(head)
    tail.next = head
    return head


def circle_lap(head):
    out = [head.value]
    node = head.next
    while node is not head:
        out.append(node.value)
        node = node.next
    return out

def is_circular(head):
    node = head.next
    while node is not None:
        if node is head:
            return True
        node = node.next
    return False


def main():
    sys.setrecursionlimit(100000)

    data = sys.stdin.read().split()
    n = int(data[0])
    values = list(map(int, data[1:1 + n]))
    c = int(data[1 + n])
    if c == 1:
        head = build_circle(values)
    else:
        head = build_singly(values)
    print(is_circular(head))


main()

